		NodeList<CFG, Statement, Edge> body = new NodeList<>(new SequentialEdge(), false);

		// with empty loops, we can skip the whole reasoning
		if (tail != conditional) {
			WorkingSet<Edge> ws = VisitOnceWorkingSet.mk(FIFOWorkingSet.mk());
