			else if (recType.isPointerType() && rectypes.anyMatch(Type::isUnitType))
				units = rectypes
						.stream()
						.filter(Type::isUnitType)
						.map(Type::asUnitType)
						.map(UnitType::getUnit)
						.collect(Collectors.toSet());
			else
