					over.getDescriptor().overrides().addAll(inherited.getDescriptor().overrides());
					over.getDescriptor().overrides().add(inherited);
					over.getDescriptor().overrides().forEach(c -> c.getDescriptor().overriddenBy().add(over));
				}
