 *             If this method returns {@code false}, the given code member
 *             is discarded.
 */
public boolean addInstanceCodeMember(CodeMember cm) {
	CodeMember c = instanceCodeMembers.putIfAbsent(cm.getDescriptor().getSignature(), cm);
