	private static String escape(String extraLabel) {
		String escapeHtml4 = StringEscapeUtils.escapeHtml4(extraLabel);
		String replace = escapeHtml4.replace("\n", "<BR/>");
		return replace.replace("\\", "\\\\");
	}

