				Interval bound = leftEval.lowIsMinusInfinity() ? leftEval : new Interval(null, leftEval.low);
				map.put((Identifier) right, bound);
				return new ValueEnvironment<Interval>(bottom(), map);
			} else
				return environment;
		case COMPARISON_GT:
			if (left instanceof Identifier) {
