				if (rightEval.lowIsMinusInfinity())
					return environment;

				Interval bound = new Interval(rightEval.low + 1, null);
				map.put((Identifier) left, bound);
				return new ValueEnvironment<Interval>(bottom(), map);
			} else if (right instanceof Identifier) {
