			builder.append(COLOR_BLACK);
			builder.append("\">");
			builder.append(COLOR_BLACK);
			builder.append("</font>, solid</td></tr>");
			builder.append("<tr><td align=\"right\">true edge&nbsp;</td><td align=\"left\"><font color=\"");
			builder.append(COLOR_BLUE);
			builder.append("\">");
			builder.append(COLOR_BLUE);
			builder.append("</font>, ");
